questionvariables.text:
/* f(x) = x^2 + b*x, b nonzero in [-5,5]; one of four planted errors. */
b       : rand_with_prohib(-5,5,[0]);
errtype : rand([1,2,3,4]);

f(x) := x^2 + b*x;
fexpr : f(x);

/* This question runs with simplification OFF (see <questionsimplify>0 above) so the
   displayed lines keep their natural, as-written term order  x^2 + 2xh + h^2 + bx +
   bh . With simp ON, Maxima re-sorts the sum (and re-sorts again when the castext
   renders {@C1@}), dropping the linear terms in among the quadratic ones. is(...)
   is used in the branch conditions because a bare "=" is not a boolean while simp
   is off. Marking is unaffected: each PRT sets autosimplify, so AlgEquiv still
   simplifies both sides and ignores term order. */

/* Correct right-hand side of each line (reference), in natural order. */
C1 : x^2 + 2*x*h + h^2 + b*x + b*h;
C2 : 2*x*h + h^2 + b*h;
C3 : 2*x + h + b;
C4 : 2*x + b;

/* Displayed lines D1..D4 (error + consistent propagation), the first wrong line,
   and the correct fix for that line. */
if is(errtype = 1) then (
  D1 : x^2 + h^2 + b*x + b*h,
  D2 : h^2 + b*h,
  D3 : h + b,
  D4 : b,
  first_wrong : 1,
  correct_fix : C1,
  err_name : "Line 1 expands (x+h)^2 as x^2 + h^2 and drops the cross term 2xh. The correct expansion is (x+h)^2 = x^2 + 2xh + h^2."
) elseif is(errtype = 2) then (
  D1 : C1,
  D2 : 2*x*h + h^2 - b*h,
  D3 : 2*x + h - b,
  D4 : 2*x - b,
  first_wrong : 2,
  correct_fix : C2,
  err_name : "Line 2 has a sign slip when subtracting f(x): the term in b should be added, not subtracted."
) elseif is(errtype = 3) then (
  D1 : C1,
  D2 : C2,
  D3 : 2*x + h^2 + b,
  D4 : 2*x + b,
  first_wrong : 3,
  correct_fix : C3,
  err_name : "Line 3 cancels h incorrectly: dividing h^2 by h gives h, not h^2. (Notice the final answer still came out right, but the working is invalid.)"
) else (
  D1 : C1,
  D2 : C2,
  D3 : C3,
  D4 : 2*x + h + b,
  first_wrong : 4,
  correct_fix : C4,
  err_name : "Line 4 forgets to take the limit: as h approaches 0 the term containing h must vanish, so it cannot remain in f'(x)."
);

/* The right-hand side actually shown on the first wrong line. */
buggy_line : [D1,D2,D3,D4][first_wrong];

/* Dropdown options: which line is the first mistake. */
wl_ta : [[1, is(first_wrong=1), "Line 1"],
         [2, is(first_wrong=2), "Line 2"],
         [3, is(first_wrong=3), "Line 3"],
         [4, is(first_wrong=4), "Line 4"]];
